{
  "avaliacoes": [
    {
      "id": "E543829615f23c3fa",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A integridade dos sistemas de offloading, incluindo mangueira de offloading, acoplamentos de separação, ponto de transferência da mangueira e amarras do navio aliviador, deve ser gerida por política do operador para inspeção, manutenção, testes, recertificação e retirada de serviço.",
          "trechos": [
            "E543829615f23c3fa:699:1397"
          ],
          "condicoes": [
            "No contexto de gestão de integridade de FPSOs/FSUs.",
            "A política deve considerar recomendações do fabricante, guias da indústria e fatores específicos da instalação, como condições meteoceanográficas, carga e número de operações."
          ],
          "limites": [
            "Fonte vinculada ao HSE do Reino Unido; não deve ser convertida automaticamente em requisito brasileiro.",
            "O trecho não define periodicidades, métodos de ensaio nem critérios numéricos de aceitação para mangueiras."
          ]
        },
        {
          "proposicao": "Revisões periódicas devem verificar mudanças de longo prazo nas características do processo e nas propriedades dos fluidos armazenados para implementar modificações necessárias à manutenção da integridade contínua.",
          "trechos": [
            "E543829615f23c3fa:0:699"
          ],
          "condicoes": [
            "Aplicável aos sistemas de carga, inertização/blanketing e offloading associados aos tanques."
          ],
          "limites": [
            "O trecho trata de gestão de integridade em nível geral e não detalha como essas revisões afetam preparação, pressurização, drenagem ou armazenamento das mangueiras."
          ]
        },
        {
          "proposicao": "O programa de inspeção deve ser capaz de identificar o início de mecanismos de degradação e falha nos componentes do sistema de amarração e arranjos de reboque de emergência, com critérios de aceitação claramente definidos.",
          "trechos": [
            "E543829615f23c3fa:1397:2096",
            "E543829615f23c3fa:2096:2441"
          ],
          "condicoes": [
            "No sistema de station-keeping, quando a avaliação de risco de integridade identifica mecanismos de degradação e modos de falha nos componentes do caminho de carga."
          ],
          "limites": [
            "O foco principal do trecho é amarração/station-keeping; sua utilidade para mangueiras é indireta.",
            "O trecho não informa quais critérios de aceitação nem como aplicá-los à inspeção de mangueiras."
          ]
        }
      ]
    },
    {
      "id": "E726d47ce491bda6c",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Deve existir procedimento de inspeção e ensaio de mangueiras para assegurar contenção durante o offloading.",
          "trechos": [
            "E726d47ce491bda6c:1383:2082"
          ],
          "condicoes": [
            "No contexto de operações de offloading e prevenção de perda de contenção."
          ],
          "limites": [
            "Fonte vinculada ao HSE do Reino Unido; não deve ser convertida automaticamente em requisito brasileiro.",
            "O trecho não especifica periodicidade, método de teste, critérios de aprovação ou formas de armazenamento."
          ]
        },
        {
          "proposicao": "Entre os mecanismos de perda de contenção em mangueiras considerados na inspeção estão impacto no convés, corrosão dos liners, kink e choque de momento associado a paradas, além de outros mecanismos de envelhecimento.",
          "trechos": [
            "E726d47ce491bda6c:1383:2082"
          ],
          "condicoes": [
            "O risco de impacto com o convés é indicado como maior quando a mangueira está cheia de líquido."
          ],
          "limites": [
            "O trecho lista perigos/mecanismos, mas não quantifica severidade, frequência ou limites operacionais."
          ]
        },
        {
          "proposicao": "Sistemas de intertravamento de permissão de bombeio podem ser usados para liberar o sinal de bombeamento apenas quando a configuração de processo e mecânica do navio aliviador estiver corretamente alinhada, devendo haver bloqueios apropriados para minimizar perda de hidrocarbonetos no offloading.",
          "trechos": [
            "E726d47ce491bda6c:1383:2082",
            "E726d47ce491bda6c:2082:2219"
          ],
          "condicoes": [
            "No tandem offloading com sistema de green line descrito pela fonte.",
            "Depende da correta configuração/alinhamento mecânico e de processo no navio aliviador."
          ],
          "limites": [
            "A fonte não afirma que esse arranjo exista em todas as instalações.",
            "O trecho não detalha arquitetura do intertravamento nem tempos de resposta."
          ]
        }
      ]
    },
    {
      "id": "E12aead011bd0c5b7",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A exportação de óleo de FPSO para a costa pode ocorrer por navio aliviador recebendo a carga por uma linha de mangueiras flexíveis, seja via boia CALM, seja diretamente do FPSO em tandem offloading.",
          "trechos": [
            "E12aead011bd0c5b7:0:696",
            "E12aead011bd0c5b7:696:1391"
          ],
          "condicoes": [
            "No recorte de exportação de óleo armazenado em F(P)SO."
          ],
          "limites": [
            "A fonte é introdutória e não detalha pressurização, drenagem, inspeção ou armazenamento das mangueiras."
          ]
        },
        {
          "proposicao": "Na boia CALM, a transferência envolve linha de mangueiras flutuantes conectada ao manifold de meia-nau do navio, enquanto a embarcação é amarrada por hawser.",
          "trechos": [
            "E12aead011bd0c5b7:696:1391"
          ],
          "condicoes": [
            "Aplicável ao arranjo de offloading por boia CALM descrito na fonte."
          ],
          "limites": [
            "Não descreve critérios de conexão segura, testes prévios ou controle operacional da linha."
          ]
        },
        {
          "proposicao": "A conexão manual da mangueira ao manifold no arranjo CALM é apresentada como atividade com riscos relevantes para pessoal, incluindo aprisionamento/esmagamento e homem ao mar, especialmente se a tripulação não estiver adequadamente treinada.",
          "trechos": [
            "E12aead011bd0c5b7:1391:1973"
          ],
          "condicoes": [
            "No cenário descrito de içamento e conexão manual da mangueira pela borda do casco."
          ],
          "limites": [
            "A fonte caracteriza perigos do arranjo descrito, não uma medida quantitativa de risco para todas as operações de offloading."
          ]
        }
      ]
    },
    {
      "id": "E14bd8d85001a79b5",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Nas operações de alívio de carga descritas, o óleo é bombeado do FPSO para o navio aliviador por mangotes especiais, e qualquer ruptura ou vazamento nesses mangotes implica derramamento de óleo na água.",
          "trechos": [
            "E14bd8d85001a79b5:691:1390"
          ],
          "condicoes": [
            "No contexto operacional de transferência entre FPSO e aliviador."
          ],
          "limites": [
            "Os diâmetros aparecem com números apagados e não podem ser reconstruídos.",
            "A fonte não informa critérios de integridade ou limites de operação dos mangotes."
          ]
        },
        {
          "proposicao": "Um procedimento de segurança citado é o teste de estanqueidade do circuito de transferência, baseado em pressurizar a linha até uma pressão pré-definida e monitorar sua pressão por determinado tempo.",
          "trechos": [
            "E14bd8d85001a79b5:1390:2087"
          ],
          "condicoes": [
            "Apresentado como exemplo de procedimento praticado na operação de alívio de carga."
          ],
          "limites": [
            "A fonte não informa valor de pressão, duração do monitoramento nem critério de aceitação.",
            "Não esclarece se o procedimento se aplica a todas as instalações."
          ]
        },
        {
          "proposicao": "Outro procedimento citado é a lavagem dos mangotes após o offloading com água não oleosa para arrastar o óleo residual, gerando água oleosa que precisa de tratamento antes do descarte ambiental.",
          "trechos": [
            "E14bd8d85001a79b5:1390:2087",
            "E14bd8d85001a79b5:2087:2287"
          ],
          "condicoes": [
            "Aplicável ao cenário em que se adota lavagem dos mangotes após a operação."
          ],
          "limites": [
            "A fonte não define volume de água, sequência detalhada de drenagem, fluido alternativo ou método de armazenamento da mangueira após lavagem.",
            "Não transforma a prática descrita em regra universal."
          ]
        }
      ]
    },
    {
      "id": "Eece7350d8cebb75a",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A transferência entre FPSO e navio aliviador é descrita com uso de mangote flutuante flexível, em operação in-tandem.",
          "trechos": [
            "Eece7350d8cebb75a:0:699",
            "Eece7350d8cebb75a:699:1399"
          ],
          "condicoes": [
            "No caso específico do FPSO Seillean descrito na fonte."
          ],
          "limites": [
            "Os números de diâmetro, comprimento, distância e capacidade estão apagados e não podem ser reconstruídos.",
            "Trata-se de descrição de instalação específica."
          ]
        },
        {
          "proposicao": "O mangote descrito possui válvulas automáticas de engate rápido nas duas extremidades, que só podem ser abertas após conexão aos respectivos flanges fixos, com a finalidade de evitar vazamentos durante conexão e desconexão.",
          "trechos": [
            "Eece7350d8cebb75a:699:1399"
          ],
          "condicoes": [
            "Aplicável ao arranjo de mangote e terminais do caso descrito."
          ],
          "limites": [
            "A fonte não informa fabricante, critérios de teste, lógica de atuação ou confiabilidade dessas válvulas."
          ]
        },
        {
          "proposicao": "Ao final do alívio, o conteúdo remanescente do mangote, incluindo água de lavagem, permanece retido pelas válvulas automáticas de engate rápido.",
          "trechos": [
            "Eece7350d8cebb75a:1399:2089"
          ],
          "condicoes": [
            "No arranjo em que as válvulas automáticas estão instaladas em ambas as extremidades do mangote."
          ],
          "limites": [
            "O trecho não detalha procedimento posterior para drenagem, esvaziamento completo, manuseio do peso residual ou armazenamento."
          ]
        }
      ]
    },
    {
      "id": "Edf19113b7159ecc0",
      "pertinente": false,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O trecho disponível repete parte da sequência final da transferência com baixa vazão, desconexão, envio do mangote e afastamento, e em seguida migra para análise funcional de subsistemas, sem acrescentar novos critérios úteis sobre preparação, testes, drenagem, inspeção ou armazenamento das mangueiras.",
          "trechos": [
            "Edf19113b7159ecc0:0:698",
            "Edf19113b7159ecc0:698:1398"
          ],
          "condicoes": [
            "Avaliação restrita aos trechos fornecidos desta fonte."
          ],
          "limites": [
            "Há sobreposição temática com achados anteriores de outra fonte do mesmo documento.",
            "Os trechos posteriores tratam de motor de combustão principal, fora do recorte de mangueiras de transferência."
          ]
        }
      ]
    }
  ],
